describe('Mobile Image Scaling - Responsive Design', () => {
  const testImageUrl = 'https://via.placeholder.com/1920x1080';
  const mobileViewports = [
    { name: 'iPhone SE', width: 375, height: 667 },
    { name: 'iPhone 12', width: 390, height: 844 },
    { name: 'iPhone 14 Pro Max', width: 430, height: 932 },
    { name: 'Samsung Galaxy S21', width: 360, height: 800 },
    { name: 'Pixel 6', width: 412, height: 915 }
  ];

  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should scale images down to fit mobile screen width on load', () => {
    cy.get('img').each(($img) => {
      cy.wrap($img).should('be.visible');
      cy.wrap($img).then(($element) => {
        const imageWidth = $element[0].getBoundingClientRect().width;
        const screenWidth = cy.state('viewportWidth');

        expect(imageWidth).to.be.lte(screenWidth);
      });
    });
  });

  it('should maintain aspect ratio while scaling images on mobile', () => {
    cy.get('img[data-testid="responsive-image"]').first().then(($img) => {
      const originalWidth = $img[0].naturalWidth;
      const originalHeight = $img[0].naturalHeight;
      const originalAspectRatio = originalWidth / originalHeight;

      cy.wrap($img).then(($element) => {
        const displayedWidth = $element[0].getBoundingClientRect().width;
        const displayedHeight = $element[0].getBoundingClientRect().height;
        const displayedAspectRatio = displayedWidth / displayedHeight;

        expect(displayedAspectRatio).to.be.closeTo(originalAspectRatio, 0.01);
      });
    });
  });

  it('should scale images correctly across multiple mobile viewports', () => {
    mobileViewports.forEach((viewport) => {
      cy.viewport(viewport.width, viewport.height);
      cy.get('img').each(($img) => {
        cy.wrap($img).should('be.visible');
        cy.wrap($img).then(($element) => {
          const imageWidth = $element[0].getBoundingClientRect().width;
          expect(imageWidth).to.be.lte(viewport.width);
        });
      });
    });
  });

  it('should handle images with max-width CSS property on mobile', () => {
    cy.get('img[style*="max-width"]').each(($img) => {
      const computedStyle = window.getComputedStyle($img[0]);
      const maxWidth = computedStyle.maxWidth;

      cy.wrap($img).then(($element) => {
        const imageWidth = $element[0].getBoundingClientRect().width;
        const screenWidth = cy.state('viewportWidth');

        expect(imageWidth).to.be.lte(screenWidth);
        if (maxWidth !== 'none') {
          expect(imageWidth).to.be.lte(parseInt(maxWidth));
        }
      });
    });
  });

  it('should not overflow container on narrow mobile screens', () => {
    cy.viewport(320, 568);
    cy.get('[data-testid="image-container"]').each(($container) => {
      cy.wrap($container).then(($element) => {
        const containerWidth = $element[0].getBoundingClientRect().width;
        const containerHeight = $element[0].getBoundingClientRect().height;

        cy.wrap($container).find('img').each(($img) => {
          const imageWidth = $img[0].getBoundingClientRect().width;
          const imageHeight = $img[0].getBoundingClientRect().height;

          expect(imageWidth).to.be.lte(containerWidth);
          expect(imageHeight).to.be.lte(containerHeight);
        });
      });
    });
  });

  it('should handle responsive images with srcset attribute', () => {
    cy.get('img[srcset]').each(($img) => {
      const srcset = $img.attr('srcset');
      expect(srcset).to.exist;

      cy.wrap($img).should('have.attr', 'src');
      cy.wrap($img).then(($element) => {
        const imageWidth = $element[0].getBoundingClientRect().width;
        const screenWidth = cy.state('viewportWidth');

        expect(imageWidth).to.be.lte(screenWidth);
      });
    });
  });

  it('should scale images correctly on orientation change', () => {
    cy.viewport('iphone-x');
    cy.get('img').first().then(($img) => {
      const portraitWidth = $img[0].getBoundingClientRect().width;

      cy.viewport('iphone-x', { orientation: 'landscape' });
      cy.get('img').first().then(($imgLandscape) => {
        const landscapeWidth = $imgLandscape[0].getBoundingClientRect().width;
        expect(landscapeWidth).to.be.greaterThan(portraitWidth);
      });
    });
  });

  it('should handle edge case of very small images on mobile', () => {
    cy.get('img[data-testid="small-image"]').each(($img) => {
      cy.wrap($img).should('be.visible');
      cy.wrap($img).then(($element) => {
        const imageWidth = $element[0].getBoundingClientRect().width;
        expect(imageWidth).to.be.greaterThan(0);
        expect(imageWidth).to.be.lte(cy.state('viewportWidth'));
      });
    });
  });

  it('should not distort images when scaling on mobile devices', () => {
    cy.viewport('iphone-x');
    cy.get('img[data-testid="test-image"]').each(($img) => {
      const naturalWidth = $img[0].naturalWidth;
      const naturalHeight = $img[0].naturalHeight;
      const naturalRatio = naturalWidth / naturalHeight;

      cy.wrap($img).then(($element) => {
        const displayWidth = $element[0].getBoundingClientRect().width;
        const displayHeight = $element[0].getBoundingClientRect().height;
        const displayRatio = displayWidth / displayHeight;

        expect(Math.abs(displayRatio - naturalRatio)).to.be.lessThan(0.02);
      });
    });
  });
});
